//! The text of `std_facade::declared`: the declarations [`declare`]
//! reads from the std table, written as the steps a new engine installs
//! (`step`).
//!
//! [`declare`]: super::declare

use std::fmt::Write;

use crate::capability;
use crate::host;
use crate::host::type_ref::{Sequence, Shape, Type};
use crate::std_facade::held;
use crate::std_facade::step;

/// The module's text so far.
pub(in crate::std_facade) struct Text(String);

impl Default for Text {
    fn default() -> Self {
        Self(String::from(
            "//! @generated by `std_facade::declare` from the std table: the std\n\
             //! facade's declarations, which a new engine installs as they are\n\
             //! (`super::step`). `scripts/std-table.sh` writes it with the table.\n\
             \n\
             use super::step::{Kind, Step, Ty};\n\
             use crate::capability;\n\
             use crate::host::type_ref::Builtin;\n\
             use crate::receiver::Mode;\n\
             \n\
             pub(super) static STEPS: &[Step] = &[\n",
        ))
    }
}

impl Text {
    /// The module's whole text.
    pub(in crate::std_facade) fn finish(mut self) -> String {
        self.0.push_str("];\n");
        self.0
    }

    fn step(&mut self, step: std::fmt::Arguments<'_>) {
        writeln!(self.0, "    Step::{step},").expect("writing to a String can't fail");
    }
}

impl super::Sink for Text {
    fn module(&mut self, path: &str) -> Result<(), host::Error> {
        self.step(format_args!("Module({path:?})"));
        Ok(())
    }

    fn held(
        &mut self,
        value: &held::Value,
        capabilities: &[capability::Kind],
    ) -> Result<(), host::Error> {
        let capabilities = capabilities
            .iter()
            .map(|kind| format!("capability::Kind::{kind:?}"))
            .collect::<Vec<_>>()
            .join(", ");
        self.step(format_args!(
            "Held {{ std: {:?}, capabilities: &[{capabilities}] }}",
            value.std
        ));
        Ok(())
    }

    fn alias(&mut self, path: &str, target: &str) -> Result<(), host::Error> {
        self.step(format_args!(
            "Alias {{ path: {path:?}, target: {target:?} }}"
        ));
        Ok(())
    }

    fn type_alias(
        &mut self,
        path: &str,
        parameters: &[&'static str],
        target: Type,
    ) -> Result<(), host::Error> {
        self.step(format_args!(
            "TypeAlias {{ path: {path:?}, parameters: &{parameters:?}, target: {} }}",
            ty(&target)
        ));
        Ok(())
    }

    fn item(
        &mut self,
        path: &str,
        kind: step::Kind,
        inputs: Vec<Type>,
        output: Type,
    ) -> Result<(), host::Error> {
        let kind = match kind {
            step::Kind::Method(mode) => format!("Method(Mode::{mode:?})"),
            kind => format!("{kind:?}"),
        };
        self.step(format_args!(
            "Item {{ path: {path:?}, kind: Kind::{kind}, inputs: {}, output: {} }}",
            types(&inputs),
            ty(&output)
        ));
        Ok(())
    }

    fn std_alias(&mut self, path: &str, std: &str) -> Result<(), host::Error> {
        self.step(format_args!("StdAlias {{ path: {path:?}, std: {std:?} }}"));
        Ok(())
    }
}

/// `types` as a static slice of [`step::Ty`].
fn types(types: &[Type]) -> String {
    let types = types.iter().map(ty).collect::<Vec<_>>().join(", ");
    format!("&[{types}]")
}

/// `ty` as a [`step::Ty`] expression.
fn ty(ty: &Type) -> String {
    match ty.shape() {
        Shape::Unit => "Ty::Unit".to_owned(),
        Shape::Builtin(builtin) => format!("Ty::Builtin(Builtin::{builtin:?})"),
        Shape::Registered { path, arguments } if arguments.is_empty() => {
            format!("Ty::Registered({:?})", path.to_string())
        }
        Shape::Parameter(name) => format!("Ty::Parameter({:?})", name.to_string()),
        Shape::Reference { mutable, target } => format!(
            "Ty::Reference {{ mutable: {mutable}, target: &{} }}",
            self::ty(target)
        ),
        Shape::Option(element) => format!("Ty::Option(&{})", self::ty(element)),
        Shape::Result(ok, err) => format!("Ty::Result(&{}, &{})", self::ty(ok), self::ty(err)),
        Shape::Array {
            element,
            sequence: Sequence::Vec,
        } => format!("Ty::Vec(&{})", self::ty(element)),
        Shape::Array {
            element,
            sequence: Sequence::Slice,
        } => format!("Ty::Slice(&{})", self::ty(element)),
        Shape::Iter(element) => format!("Ty::Iter(&{})", self::ty(element)),
        Shape::Boxed(element) => format!("Ty::Boxed(&{})", self::ty(element)),
        shape => panic!("a std facade step holds no `{shape:?}`; give `step::Ty` one"),
    }
}
